// Classify the raw reading; this never rewrites devicePixelRatio. Exact DPRs
// keep their original meaning. The one amended representation needs the
// separately captured native-window and screenshot identity as well.
export function visualDprIdentity(input){
 const {requested,actual,registered:r,capture:c,native_display:n}=input;
 const result={requested_dpr:requested,actual_dpr:actual,recognized:false,target_identity_basis:null,missing_evidence:[]};
 if(![1,1.25].includes(requested)||!Number.isFinite(actual))return result;
 if(actual===requested)return {...result,recognized:true,target_identity_basis:'exact-raw-target'};
 const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b),nativeWindows=n?.windows,configuration=nativeConfiguration(n);
 if(!r?.native_configuration)result.missing_evidence.push('Registered historical native OS/DPI/monitor configuration absent; historical JS screen and PNG cannot substitute');
 if(!configuration)result.missing_evidence.push('Actual native OS/DPI/monitor configuration unavailable');
 const supportedViewport= same(input.viewport,[1366,768])||same(input.viewport,[1920,1080]);
 if(requested===1&&actual===1.0000000149011612&&r?.raw_DPR_exact===actual&&
    input.carrier===r.carrier&&input.browser_version===r.browser_version&&input.executable===r.executable&&
    supportedViewport&&same(input.viewport,r.css_viewport)&&input.zoom===1&&
    r.default_windows_installation===true&&same(r.custom_launch_args,[])&&r.network_or_permission_changes===false&&
    c?.screenshot_scale==='device'&&same(c.png_ihdr,input.viewport)&&
    same(c.requested_context,{viewport:{width:input.viewport[0],height:input.viewport[1]},deviceScaleFactor:1})&&
    n?.available===true&&configuration&&r.native_configuration&&same(configuration,r.native_configuration)&&Array.isArray(nativeWindows)&&nativeWindows.length>0&&nativeWindows.every(w=>
     Number.isInteger(w.pid)&&w.pid>0&&typeof w.hwnd==='string'&&w.hwnd.length>0&&Number.isInteger(w.dpi)&&w.dpi>0))
  return {...result,recognized:true,target_identity_basis:'B24-OUTCOME-DESIGN-1.0.3'};
 return result;
}
// This is a fresh same-session registration, never a replacement for missing
// historical evidence. Pixel comparison and the before/after native identity
// checks remain separate requirements of the actual paired capture.
export function visualCurrentPairDprIdentity(input,registration){
 const refused={requested_dpr:input.requested,actual_dpr:input.actual,recognized:false,target_identity_basis:null,missing_evidence:['Complete pre-capture current native registration required']};
 if(registration?.version!=='B24-CURRENT-PAIR-NATIVE-VERIFICATION-1'||!Number.isFinite(Date.parse(registration.registered_at))||!registration.native_configuration)return refused;
 const result=visualDprIdentity({...input,registered:registration});
 return result.recognized?{...result,target_identity_basis:registration.version}:result;
}
function nativeConfiguration(reading){
 if(typeof reading?.os_version!=='string'||!Array.isArray(reading.windows)||!reading.windows.length)return null;
 const rect=box=>box&&['left','top','right','bottom'].every(key=>Number.isFinite(box[key]))&&box.right>box.left&&box.bottom>box.top;
 if(!reading.windows.every(window=>Number.isInteger(window.dpi)&&window.dpi>0&&[0,1,2].includes(window.awareness)&&rect(window.monitor?.bounds)&&rect(window.monitor?.work)&&Number.isInteger(window.monitor.flags)))return null;
 return {os_version:reading.os_version,windows:reading.windows.map(({dpi,awareness,monitor})=>({dpi,awareness,monitor:{bounds:monitor.bounds,work:monitor.work,flags:monitor.flags}}))};
}

// Independent formulas for the two existing map implementations. These values
// are checked against each browser's own CSS width serialization/layout, never
// against a new floating-point or pixel tolerance.
export function expectedVisualScale(kind,cameraScale){
 assert(Number.isFinite(cameraScale)&&cameraScale>0,'Positive actual map camera scale required');
 if(kind==='reference')return {value:100,css_line_px:Math.round(100*cameraScale),rule:'fixed100-round-css-pixel'};
 assert.equal(kind,'current');const target=100/cameraScale,power=10**Math.floor(Math.log10(target)),ratio=target/power;
 const value=(ratio>=10?10:ratio>=5?5:ratio>=2?2:1)*power;
 return {value,css_line_px:value*cameraScale,rule:'nice-step-below100-css-pixels'};
}

export function reportVisibleColumn({workbody,list}){
 for(const box of [workbody,list])assert(box&&['left','top','right','bottom','width','height'].every(k=>Number.isFinite(box[k]))&&box.width>0&&box.height>0,'Actual report ancestor/list boxes required');
 assert.equal(list.left,workbody.left,'Report list must start at the actual work-area left');
 assert.equal(list.top,workbody.top,'Report list must start at the actual work-area top');
 assert(list.right>workbody.left&&list.right<workbody.right,'Report list must leave a positive visible report column');
 const x=list.right,y=workbody.top,width=workbody.right-list.right,height=workbody.height;
 return {x,y,width,height,left:x,top:y,right:workbody.right,bottom:workbody.bottom};
}
export function reportGeometryIdentity({column,article,expected,ancestors}){
 const same=(a,b)=>['left','top','right','bottom','width','height'].every(key=>Number.isFinite(a?.[key])&&a[key]===b?.[key]);
 const intersection=(a,b,x=true,y=true)=>{const left=x?Math.max(a.left,b.left):a.left,right=x?Math.min(a.right,b.right):a.right,top=y?Math.max(a.top,b.top):a.top,bottom=y?Math.min(a.bottom,b.bottom):a.bottom;return {x:left,y:top,left,top,right,bottom,width:Math.max(0,right-left),height:Math.max(0,bottom-top)};};
 const expectedVisible=intersection(column,article);let visible=expectedVisible;
 for(const ancestor of ancestors){const clip=value=>['hidden','clip','auto','scroll'].includes(value);visible=intersection(visible,ancestor.box,clip(ancestor.overflow_x),clip(ancestor.overflow_y));}
 return {valid:same(article,expected)&&same(visible,expectedVisible)&&visible.width>0&&visible.height>0,expected_geometry:expected,expected_visible:expectedVisible,actual_visible:visible};
}

function nativeDisplay(profile){
 let processes;try{processes=ownedProcesses(profile);assert(processes.length>0,'Actual owned browser process required');}catch(error){return {available:false,windows:[],error:String(error),at:new Date().toISOString()};}const pids=processes.map(row=>row.pid);
 const script=`$ErrorActionPreference='Stop'
Add-Type -TypeDefinition @'
using System;using System.Runtime.InteropServices;
public static class B24ReadonlyDisplay {
 [StructLayout(LayoutKind.Sequential)] public struct Rect {public int left,top,right,bottom;}
 [StructLayout(LayoutKind.Sequential)] public struct Monitor {public int size;public Rect bounds,work;public uint flags;}
 [DllImport("user32.dll")] public static extern uint GetDpiForWindow(IntPtr window);
 [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr window,out Rect rect);
 [DllImport("user32.dll")] public static extern IntPtr MonitorFromWindow(IntPtr window,uint flags);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern bool GetMonitorInfoW(IntPtr monitor,ref Monitor info);
 [DllImport("user32.dll")] public static extern IntPtr GetWindowDpiAwarenessContext(IntPtr window);
 [DllImport("user32.dll")] public static extern int GetAwarenessFromDpiAwarenessContext(IntPtr context);
}
'@
$windows=@(foreach($ownedId in ($env:B24_DISPLAY_PIDS -split ',')) {
 $ownedProcess=Get-Process -Id ([int]$ownedId) -ErrorAction SilentlyContinue
 if($ownedProcess -and $ownedProcess.MainWindowHandle -ne 0) {
  $handle=$ownedProcess.MainWindowHandle;$rect=[B24ReadonlyDisplay+Rect]::new()
  if(-not [B24ReadonlyDisplay]::GetWindowRect($handle,[ref]$rect)){throw 'Actual owned window bounds unavailable'}
  $monitor=[B24ReadonlyDisplay]::MonitorFromWindow($handle,2);$info=[B24ReadonlyDisplay+Monitor]::new();$info.size=[Runtime.InteropServices.Marshal]::SizeOf($info)
  if(-not [B24ReadonlyDisplay]::GetMonitorInfoW($monitor,[ref]$info)){throw 'Actual owned monitor unavailable'}
  @{pid=[int]$ownedId;hwnd=$handle.ToString();dpi=[int][B24ReadonlyDisplay]::GetDpiForWindow($handle);window=$rect;monitor_handle=$monitor.ToString();monitor=$info;awareness=[B24ReadonlyDisplay]::GetAwarenessFromDpiAwarenessContext([B24ReadonlyDisplay]::GetWindowDpiAwarenessContext($handle))}
 }
})
ConvertTo-Json -Depth 6 -Compress -InputObject @{available=($windows.Count -gt 0);windows=$windows;os_version=[Environment]::OSVersion.VersionString;readonly_apis=$true}`;
 try{return {...JSON.parse(execFileSync('powershell.exe',['-NoProfile','-NonInteractive','-Command',script],{encoding:'utf8',timeout:10000,windowsHide:true,env:{...process.env,B24_DISPLAY_PIDS:pids.join(',')}})),processes,at:new Date().toISOString()};}
 catch(error){return {available:false,windows:[],processes,error:String(error),at:new Date().toISOString()};}
}

async function mapFacts(target,kind){
 const actual=await target.evaluate(kind=>{
  const scale=document.querySelector('.scale'),line=scale?.querySelector('i');if(!scale||!line)return null;
  const s=getComputedStyle(scale),l=getComputedStyle(line),overlay=document.querySelector('.world-overlay'),canvas=document.querySelector('.map-canvas');
  const camera=kind==='reference'?(overlay?new DOMMatrix(getComputedStyle(overlay).transform).a:null):Number(canvas?.getAttribute('data-camera')?.split(',')[2]);
  const text=[...scale.childNodes].find(node=>node.nodeType===Node.TEXT_NODE&&node.textContent.includes('图上米'));
  let unit=null;if(text){const range=document.createRange();range.setStart(text,text.textContent.indexOf('图上米'));range.setEnd(text,text.textContent.length);unit=range.getBoundingClientRect().toJSON();}
  return {camera_scale:camera,text:scale.textContent,box:scale.getBoundingClientRect().toJSON(),unit_box:unit,
   fixed:{font_family:s.fontFamily,font_size:s.fontSize,font_weight:s.fontWeight,line_height:s.lineHeight,color:s.color,gap:s.gap,align_items:s.alignItems,display:s.display,padding:s.padding,border:[s.borderTop,s.borderRight,s.borderBottom,s.borderLeft]},
   line:{box:line.getBoundingClientRect().toJSON(),declared_width:line.style.width,computed_width:l.width,box_sizing:l.boxSizing,padding:l.padding,
    fixed:{height:l.height,border_top:l.borderTop,border_right:l.borderRight,border_bottom:l.borderBottom,border_left:l.borderLeft,background:l.backgroundColor}}};
 },kind);
 if(!actual)return null;const expected=expectedVisualScale(kind,actual.camera_scale),parsed=actual.text?.match(/^(\d+(?:\.\d+)?)\s+图上米$/);
 actual.expected=expected;actual.numeric_value=parsed?Number(parsed[1]):null;
 actual.expected_declared_width=await target.evaluate(width=>{const probe=document.createElement('i');probe.style.width=width+'px';return probe.style.width;},expected.css_line_px);
 return actual;
}

