async function comparePixels(a,b){
 const decoder=await context.newPage();try{return await decoder.evaluate(async({a,b})=>{async function decode(encoded){const image=new Image();image.src='data:image/png;base64,'+encoded;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);return{width:image.width,height:image.height,pixels:ctx.getImageData(0,0,image.width,image.height).data};}const x=await decode(a),y=await decode(b);if(x.width!==y.width||x.height!==y.height)return{status:'not_comparable',dimensions:[[x.width,x.height],[y.width,y.height]]};let diff_pixels=0;for(let i=0;i<x.pixels.length;i+=4)if([0,1,2,3].some(channel=>x.pixels[i+channel]!==y.pixels[i+channel]))diff_pixels++;return{status:'compared',width:x.width,height:x.height,diff_pixels,rgba_bits:8,threshold:0};},{a:(await fs.readFile(path.join(plan.artifact_root,a))).toString('base64'),b:(await fs.readFile(path.join(plan.artifact_root,b))).toString('base64')});}finally{await decoder.close();}
}
