  result.background=background;assert(background.chain.every(node=>node.image==='none'),'Controlled tool background contains an unregistered image');
  assert.equal(background.chain.find(node=>node.background!=='rgba(0, 0, 0, 0)')?.background,'rgb(28, 41, 41)','Own original CSS must supply the registered neutral background');
  assert(background.bitmaps.every(bitmap=>JSON.stringify(bitmap.pixel)==='[0,0,0,0]'),'No copied/drawn terrain in the independent component carrier');assert.deepEqual(workers,[]);
